/// True when `(surah, from, to)` is one of the meaning-safe spans.
pub fn is_safe_range(surah: u16, from: u16, to: u16) -> bool {
    SAFE_RANGES
        .binary_search(&(surah, from, to))
        .is_ok()
}

/// Arabic name of a surah (empty when out of range).
pub fn surah_name(surah: u16) -> &'static str {
    SURAHS
        .iter()
        .find(|(n, _)| *n == surah)
        .map(|(_, name)| *name)
        .unwrap_or("")
}
